// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0) && token != address(c));
        // ensure token is not already added (if it was, revert is expected)
        // we only test after addReward succeeds
        // we call addReward, then check rewardPeriodFinish > 0
        // use try/catch because addReward may revert if token already added
        try c.addReward(token) {
            // addReward succeeded, now rewardPeriodFinish must be > 0
            assertTrue(c.rewardPeriodFinish(token) > 0, "rewardPeriodFinish should be > 0 after addReward");
        } catch {
            // if addReward reverts (e.g. token already added), skip
            // but we still need to ensure that if already added, rewardPeriodFinish is > 0
            // if token was added before, it must have periodFinish > 0
            // we can't know for sure, but we can assume it was not added before, so skip
        }
    }
}

